import{_ as a,o as d,c as n,a5 as r}from"./chunks/framework.a5no_H3L.js";const p=JSON.parse('{"title":"x64dbg 动态调试实操","description":"上一篇讲了断点和单步的原理，这一篇把它们落到 x64dbg——Windows 用户态调试的事实标准，免费开源，是动态分析的主战场。","frontmatter":{"type":"howto","level":"basic"},"headers":[],"relativePath":"reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md","filePath":"reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"}'),i={name:"reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"};function t(g,e,c,s,l,o){return d(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="x64dbg-动态调试实操" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 动态调试实操 <a class="header-anchor" href="#x64dbg-动态调试实操" aria-label="Permalink to &quot;x64dbg 动态调试实操&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><p data-src-line="4" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">上一篇讲了断点和单步的原理，这一篇把它们落到 x64dbg——Windows 用户态调试的事实标准，免费开源，是动态分析的主战场。</p></blockquote><p data-src-line="6" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>前置条件</strong>：已读 <a href="./chapter-01-debugging-basics.html">调试器的断点与单步机制</a>，理解软件断点、硬件断点、单步的含义；电脑上装好 x64dbg（本文以 2025 年的版本为准，界面和快捷键长期稳定）。练手目标用<a href="./../01-program-basics/chapter-01-c-cpp-compilation.html">编译篇的 crackme.c</a>——一个读输入、校验、打印对错的小程序。</p><h2 id="_1-安装与启动" tabindex="-1" data-src-line="8" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">1. 安装与启动 <a class="header-anchor" href="#_1-安装与启动" aria-label="Permalink to &quot;1. 安装与启动&quot;">​</a></h2><p data-src-line="10" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 是免安装的：从 <a href="https://x64dbg.com/" target="_blank" rel="noreferrer">x64dbg.com</a> 下载 snapshot 压缩包，解压后双击 <code>x96dbg.exe</code> 启动，它会让你选择启动 32 位（<code>x32dbg</code>）还是 64 位（<code>x64dbg</code>）调试器。分析 64 位程序选 <strong>x64dbg</strong>，分析 32 位程序选 x32dbg——用错位数会直接无法加载。</p><p data-src-line="12" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">打开后是空的工作区。用 <code>File → Open</code>（或按 <code>F3</code>）选择你的 <code>.exe</code>，程序会被加载并停在<strong>系统断点</strong>（entry breakpoint）处，通常位于 <code>ntdll.dll</code> 里，还没到你的代码。</p><h2 id="_2-认识-cpu-窗口" tabindex="-1" data-src-line="14" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">2. 认识 CPU 窗口 <a class="header-anchor" href="#_2-认识-cpu-窗口" aria-label="Permalink to &quot;2. 认识 CPU 窗口&quot;">​</a></h2><p data-src-line="16" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 的核心是 <strong>CPU 窗口</strong>，它由四个面板组成，各有明确分工：</p><table tabindex="0"><thead data-src-line="18" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><tr data-src-line="18" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><th style="text-align:left;">面板</th><th style="text-align:left;">位置</th><th style="text-align:left;">内容</th></tr></thead><tbody data-src-line="20" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><tr data-src-line="20" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">反汇编</td><td style="text-align:left;">左上</td><td style="text-align:left;">当前地址附近的反汇编，最常用</td></tr><tr data-src-line="21" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">寄存器</td><td style="text-align:left;">右上</td><td style="text-align:left;">各寄存器的值，可双击修改</td></tr><tr data-src-line="22" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">内存 dump</td><td style="text-align:left;">左下</td><td style="text-align:left;">某块内存的十六进制内容</td></tr><tr data-src-line="23" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">栈</td><td style="text-align:left;">右下</td><td style="text-align:left;">当前线程的栈，含调用返回地址</td></tr></tbody></table><p data-src-line="25" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">几个高频快捷键先记住：<code>F9</code> 运行、<code>F12</code> 暂停、<code>F7</code> 单步步入（进入函数）、<code>F8</code> 单步步过（跳过函数）、<code>F2</code> 切换断点、<code>Ctrl+G</code> 跳转到地址、<code>Ctrl+F2</code> 重启程序。</p><h2 id="_3-下断点-跑到关键处" tabindex="-1" data-src-line="27" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">3. 下断点，跑到关键处 <a class="header-anchor" href="#_3-下断点-跑到关键处" aria-label="Permalink to &quot;3. 下断点，跑到关键处&quot;">​</a></h2><p data-src-line="29" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">先在反汇编面板跳到你想停的位置（<code>Ctrl+G</code> 输入地址或函数名，如 <code>main</code> 或 <code>&amp;&quot;Wrong password&quot;</code> 所在逻辑），然后按 <code>F2</code> 在该行下断点——该行会变红。按 <code>F9</code> 运行，程序跑到断点处自动停下。</p><p data-src-line="31" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">一个定位关键点的实用技巧：如果程序里有一段「正确密码」的判断，你可以先用字符串搜索（反汇编面板右键 <code>Search for → String references</code>，或 <code>Ctrl+F</code>）找到 <code>&quot;Wrong password&quot;</code> 字符串的位置，<code>Ctrl+G</code> 跳到引用它的比较指令附近，在那里下断点。</p><p data-src-line="33" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">停到断点后，寄存器面板里 <strong>RIP</strong> 就是当前指令地址。此时你已经站在「程序运行到这一瞬间」的现场，可以开始观察。</p><h2 id="_4-单步跟踪-观察分支" tabindex="-1" data-src-line="35" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">4. 单步跟踪，观察分支 <a class="header-anchor" href="#_4-单步跟踪-观察分支" aria-label="Permalink to &quot;4. 单步跟踪，观察分支&quot;">​</a></h2><p data-src-line="37" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">停在比较指令附近后，用单步看清楚程序走哪条分支：</p><ul data-src-line="39" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><li data-src-line="39" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><code>F7</code>（步入）：执行一条指令，如果该指令是 <code>call</code>，会<strong>进入</strong>被调函数内部。</li><li data-src-line="40" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><code>F8</code>（步过）：执行一条指令，如果该指令是 <code>call</code>，会<strong>执行完整个函数</strong>再停到下一行。</li></ul><p data-src-line="42" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">对「观察这段逻辑走哪条分支」来说，多用 <code>F8</code> 跳过不关心的函数调用，只在想深入某个函数时才用 <code>F7</code>。每走一步，观察寄存器面板的变化，尤其是 <code>RAX</code>（常是返回值）和标志位（决定条件跳转）。</p><p data-src-line="44" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">走到 <code>cmp ... / jne ...</code> 这类指令时，留意反汇编面板右侧的跳转提示：x64dbg 会在跳转目标旁标注箭头，命中与否一目了然。</p><h2 id="_5-查看和修改内存、寄存器" tabindex="-1" data-src-line="46" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">5. 查看和修改内存、寄存器 <a class="header-anchor" href="#_5-查看和修改内存、寄存器" aria-label="Permalink to &quot;5. 查看和修改内存、寄存器&quot;">​</a></h2><p data-src-line="48" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">调试的核心动作之一，是看内存里的数据。在内存 dump 面板，<code>Ctrl+G</code> 输入地址即可跳转查看。要「跟着某个寄存器指向的内存看」，右键该寄存器选「Follow in Dump」即可把 dump 面板切到那个地址。</p><p data-src-line="50" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">寄存器可以<strong>直接双击修改</strong>，用于改变执行走向（比如把标志位改掉让条件跳转反着走）。但更持久、更实用的修改方式是<strong>打补丁</strong>，见下一节。</p><h2 id="patching" tabindex="-1" data-src-line="52" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">6. 打补丁：直接改机器码 <a class="header-anchor" href="#patching" aria-label="Permalink to &quot;6. 打补丁：直接改机器码 {#patching}&quot;">​</a></h2><p data-src-line="54" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">「打补丁」指的是直接修改程序在内存（进而可写回文件）里的机器码，改变程序行为。典型场景：把「校验失败跳走」改成「永远判定成功」。</p><p data-src-line="56" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">操作步骤：</p><ol data-src-line="58" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><li data-src-line="58" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">在反汇编面板选中要改的指令（比如那条 <code>jne</code>），按<strong>空格键</strong>，输入新的汇编指令（如 <code>je</code> 或 <code>nop</code>）。</li><li data-src-line="59" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 会提示「汇编后字节数可能变化」，确认后该指令被替换。</li><li data-src-line="60" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">按 <code>F9</code> 继续运行，观察程序行为是否如预期改变。</li></ol><p data-src-line="62" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">修改只影响当前内存。若要<strong>永久保存到文件</strong>，用 <code>File → Patch file</code>（或右键 <code>Patches</code>），x64dbg 会把改动写回磁盘生成新的 <code>.exe</code>。</p><blockquote data-src-line="64" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><p data-src-line="64" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">补丁是逆向学习里「验证理解」的极好手段：你以为某个跳转是关键，就把它改掉，看程序行为是否按你的预期变化。改对了，说明你读懂了；改错了，说明判断有偏差，回去重新读。这只应作用于你自编的练手程序或授权目标。</p></blockquote><h2 id="_7-硬件断点与内存断点" tabindex="-1" data-src-line="66" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">7. 硬件断点与内存断点 <a class="header-anchor" href="#_7-硬件断点与内存断点" aria-label="Permalink to &quot;7. 硬件断点与内存断点&quot;">​</a></h2><p data-src-line="68" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><a href="./chapter-01-debugging-basics.html">调试器的断点与单步机制</a>讲过三类断点的区别。x64dbg 里它们分别这样下：</p><ul data-src-line="70" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><li data-src-line="70" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>软件断点</strong>：反汇编面板按 <code>F2</code>。</li><li data-src-line="71" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>硬件断点</strong>：<code>Debug → Hardware breakpoints</code>，或在寄存器面板下方查看；可设执行/读/写，最多 4 个。</li><li data-src-line="72" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>内存断点</strong>：在内存 dump 面板选中一段内存，右键 <code>Breakpoint → Memory, Access/Write</code>。</li></ul><p data-src-line="74" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">需要「监视某变量何时被改写」时用内存/硬件写断点；断点总被程序莫名清掉（可能是自校验）时，改用硬件断点。</p><h2 id="_8-条件断点与-api-断点" tabindex="-1" data-src-line="76" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">8. 条件断点与 API 断点 <a class="header-anchor" href="#_8-条件断点与-api-断点" aria-label="Permalink to &quot;8. 条件断点与 API 断点&quot;">​</a></h2><p data-src-line="78" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">普通断点一命就停，但很多场景需要更精细的控制。两种进阶断点解决这个问题。</p><h3 id="_8-1-条件断点-满足条件才停" tabindex="-1" data-src-line="80" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">8.1 条件断点：满足条件才停 <a class="header-anchor" href="#_8-1-条件断点-满足条件才停" aria-label="Permalink to &quot;8.1 条件断点：满足条件才停&quot;">​</a></h3><p data-src-line="82" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">条件断点给断点加一个「命中条件」，只有条件为真才停下。典型场景：</p><ul data-src-line="84" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><li data-src-line="84" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">循环执行 1000 次，只想在第 500 次停下。</li><li data-src-line="85" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">只想在某个参数等于特定值时停下。</li></ul><p data-src-line="87" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 下条件断点：在断点上右键 → <code>Edit breakpoint</code>（或 <code>Breakpoint</code> 面板），在条件框里写表达式，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eax == 0x100    ; EAX 等于 0x100 才停</span></span>
<span class="line"><span>ecx &gt; 10        ; ECX 大于 10 才停</span></span></code></pre></div><p data-src-line="94" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">命中条件不满足时，断点会「透明地」放行，程序继续跑。这样你能在「海量调用里精准抓到一次感兴趣的调用」，而不是手动按几百次 <code>F9</code>。</p><h3 id="_8-2-api-断点-在系统函数上停" tabindex="-1" data-src-line="96" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">8.2 API 断点：在系统函数上停 <a class="header-anchor" href="#_8-2-api-断点-在系统函数上停" aria-label="Permalink to &quot;8.2 API 断点：在系统函数上停&quot;">​</a></h3><p data-src-line="98" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">API 断点是「在 Windows API 函数上下断点」。程序要读写文件、联网、查注册表，最终都要调用对应的系统函数，在这些函数上断点，就能在「程序做某类操作」的瞬间停下来。</p><p data-src-line="100" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">x64dbg 下 API 断点：在命令栏输入 API 名，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bp CreateFileW     ; 在创建文件时停下</span></span>
<span class="line"><span>bp send            ; 在发送网络数据时停下</span></span>
<span class="line"><span>bp RegSetValueExW  ; 在写注册表时停下</span></span></code></pre></div><p data-src-line="108" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">命中后，看寄存器和栈就能拿到参数——<code>CreateFileW</code> 的第一个参数（RCX）是文件名，<code>send</code> 的缓冲区参数是要发送的数据。</p><p data-src-line="110" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">API 断点的价值：<strong>你不必先找到程序里调用它的位置，直接按行为下断点</strong>。想追踪「程序打开了哪些文件」，断 <code>CreateFileW</code>；想追踪「发了什么数据」，断 <code>send</code>。这是从「行为」角度切入动态分析的最快方式。</p><h3 id="_8-3-什么时候用哪种" tabindex="-1" data-src-line="112" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">8.3 什么时候用哪种 <a class="header-anchor" href="#_8-3-什么时候用哪种" aria-label="Permalink to &quot;8.3 什么时候用哪种&quot;">​</a></h3><table tabindex="0"><thead data-src-line="114" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><tr data-src-line="114" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><th style="text-align:left;">场景</th><th style="text-align:left;">用哪种</th></tr></thead><tbody data-src-line="116" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><tr data-src-line="116" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">循环里只断特定迭代</td><td style="text-align:left;">条件断点</td></tr><tr data-src-line="117" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">只断特定参数值</td><td style="text-align:left;">条件断点</td></tr><tr data-src-line="118" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">追踪文件/网络/注册表操作</td><td style="text-align:left;">API 断点</td></tr><tr data-src-line="119" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><td style="text-align:left;">监视变量被改写</td><td style="text-align:left;">硬件/内存断点（上一节）</td></tr></tbody></table><h2 id="_9-失败与回退" tabindex="-1" data-src-line="121" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">9. 失败与回退 <a class="header-anchor" href="#_9-失败与回退" aria-label="Permalink to &quot;9. 失败与回退&quot;">​</a></h2><ul data-src-line="123" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><li data-src-line="123" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>程序加载后直接退出或异常</strong>：可能程序检测到调试器（<a href="./../07-packing/chapter-03-virtualization-anti-debugging.html">反调试与反静态分析</a>），或位数选错。先确认用的是 x64dbg 还是 x32dbg。</li><li data-src-line="124" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>断点不命中</strong>：检查是否打在指令中间，或该路径根本没被执行。</li><li data-src-line="125" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>改乱指令想重来</strong>：<code>Ctrl+F2</code> 重启程序，内存里的临时修改会还原；若已写回文件，重新用原始 <code>.exe</code> 打开。</li><li data-src-line="126" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><strong>栈/寄存器面板看不懂</strong>：回到<a href="./chapter-01-debugging-basics.html">调试器的断点与单步机制</a>，对照「寄存器、内存、调用栈」的含义。</li></ul><hr><blockquote data-src-line="130" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md"><p data-src-line="130" data-src-file="reverse-engineering/06-dynamic-debugging/chapter-02-x64dbg.md">本章走通了 x64dbg 的一次完整动态调试：下断点、单步跟踪、观察分支、打补丁改变行为。下一章开始面对真实世界的阻力——<a href="./../07-packing/chapter-03-virtualization-anti-debugging.html">反调试与反静态分析</a>，看程序如何发现并反抗你的调试。</p></blockquote>`,52)])])}const h=a(i,[["render",t]]);export{p as __pageData,h as default};
